<template><section class="customer-panel q-mt-lg"><h2 class="section-heading">Customer password recovery</h2><p class="page-subtitle q-mb-md">Verify the customer's identity before setting a new password. Other sessions will be signed out; an enrolled authenticator remains required.</p><q-banner v-if="message" class="bank-feedback q-mb-md">{{ message }}</q-banner><q-form ref="resetForm" class="customer-form" @submit="reset"><search-select v-model="customerId" filled label="Customer" :options="customers" emit-value map-options :rules="[v => !!v || 'Choose a customer']" /><q-input v-model="staffPassword" filled type="password" autocomplete="current-password" label="Your staff password" :rules="[v => !!v || 'Required']" /><NewPasswordField v-model="newPassword" label="Customer's new password" /><q-checkbox v-model="confirmed" label="I verified this customer's identity" /><q-btn label="Reset customer password" color="primary" type="submit" :loading="busy" :disable="!confirmed" /></q-form></section></template>
<script setup>
import { ref, onMounted, nextTick } from 'vue'
import api from '@/services/api'
import NewPasswordField from '@/components/NewPasswordField.vue'
const customers=ref([]),customerId=ref(null),staffPassword=ref(''),newPassword=ref(''),confirmed=ref(false),busy=ref(false),message=ref(''),resetForm=ref(null)
onMounted(async()=>{try{customers.value=(await api.get('/staff/customer-access/')).data.map(c=>({label:`${c.name} · ${c.username}`,value:c.id}))}catch{message.value='Could not load customers. Refresh to retry.'}})
async function reset(){if(busy.value||!confirmed.value)return;busy.value=true;message.value='';try{await api.post(`/staff/customer-access/${customerId.value}/password`,{staff_password:staffPassword.value,new_password:newPassword.value,identity_confirmed:true});staffPassword.value='';newPassword.value='';confirmed.value=false;await nextTick();resetForm.value?.resetValidation();message.value='Password updated. Give the new password to the customer privately.'}catch(e){message.value=e.response?.data?.detail||'Could not reset this password.'}finally{busy.value=false}}
</script>
